#!/usr/bin/env python3 -I
"""Seed deterministic demo data for agents (KAN-98).

Registers three demo sources in Postgres, runs the DocumentHarvester against the
fixture docs directory, and upserts the lineage chain entities/edges and broken-job
entity that the four demo agents (docs/DEMO_AGENTS.md) depend on.

Usage:
    python scripts/seed_demo.py [--fixtures-dir <path>] [--database-url <url>]

Defaults:
    --fixtures-dir  <repo-root>/fixtures  (generated by scripts/generate_fixtures.py)
    --database-url  $DATABASE_URL or postgresql://postgres:postgres@localhost:5432/postgres
"""
from __future__ import annotations

import argparse
import os
import sys
import uuid
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

import psycopg

from scripts.generate_fixtures import generate as _generate_fixtures
from harvesters.base import Chunk, Entity, Edge
from harvesters.document.harvester import DocumentHarvester
from harvesters.framework import HarvestPlan

_ONTOLOGY = "v0"
_EMBEDDING_MODEL = "seed"  # no embedder running during seed; embedding stays NULL


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def _upsert_source(conn: psycopg.Connection, type_: str, uri: str, owner: str, sensitivity: str) -> str:
    """Insert a source row (idempotent on type+uri) and return its UUID."""
    row = conn.execute(
        "SELECT id FROM sources WHERE type = %s AND uri = %s",
        (type_, uri),
    ).fetchone()
    if row:
        return str(row[0])
    row = conn.execute(
        """
        INSERT INTO sources (id, type, uri, owner, sensitivity, status)
        VALUES (gen_random_uuid(), %s, %s, %s, %s, 'active')
        RETURNING id
        """,
        (type_, uri, owner, sensitivity),
    ).fetchone()
    return str(row[0])


def _upsert_entity(conn: psycopg.Connection, source_id: str, entity: Entity) -> str:
    """Upsert an entity and return its DB UUID."""
    row = conn.execute(
        """
        INSERT INTO entities (id, type, name, source_id, external_id, props, ontology_version)
        VALUES (gen_random_uuid(), %s, %s, %s::uuid, %s, %s::jsonb, %s)
        ON CONFLICT (source_id, external_id) DO UPDATE
            SET type = EXCLUDED.type,
                name = EXCLUDED.name,
                props = EXCLUDED.props,
                ontology_version = EXCLUDED.ontology_version,
                tombstoned_at = NULL
        RETURNING id
        """,
        (
            entity.type,
            entity.name,
            source_id,
            entity.external_id,
            _json(entity.props),
            _ONTOLOGY,
        ),
    ).fetchone()
    return str(row[0])


def _upsert_edge(
    conn: psycopg.Connection,
    source_id: str,
    edge: Edge,
    entity_id_map: dict[str, str],
) -> None:
    src_id = entity_id_map.get(edge.src_external_id)
    dst_id = entity_id_map.get(edge.dst_external_id)
    if not src_id or not dst_id:
        print(
            f"  [WARN] skipping edge {edge.relation} {edge.src_external_id!r} "
            f"-> {edge.dst_external_id!r}: entity not found in map",
            file=sys.stderr,
        )
        return
    conn.execute(
        """
        INSERT INTO edges (id, src_entity_id, dst_entity_id, relation, confidence, source_id, ontology_version)
        VALUES (gen_random_uuid(), %s::uuid, %s::uuid, %s, %s, %s::uuid, %s)
        ON CONFLICT DO NOTHING
        """,
        (src_id, dst_id, edge.relation, edge.confidence, source_id, _ONTOLOGY),
    )


def _insert_chunk(
    conn: psycopg.Connection,
    source_id: str,
    chunk: Chunk,
    entity_id_map: dict[str, str],
) -> None:
    entity_id = entity_id_map.get(chunk.entity_external_id)
    if not entity_id:
        return
    conn.execute(
        """
        INSERT INTO chunks (id, entity_id, source_id, text, embedding_model, metadata, harvested_at)
        VALUES (gen_random_uuid(), %s::uuid, %s::uuid, %s, %s, %s::jsonb, now())
        """,
        (entity_id, source_id, chunk.text, _EMBEDDING_MODEL, _json(chunk.metadata)),
    )


def _json(value: dict) -> str:
    import json
    return json.dumps(value)


# ---------------------------------------------------------------------------
# Lineage chain seed data
# ---------------------------------------------------------------------------

def _lineage_entities(source_id: str) -> list[Entity]:
    """Return Table/Dashboard/Job entities for the sql-dbt lineage chain."""
    return [
        Entity(
            type="Table",
            name="source_orders",
            external_id="table:source_orders",
            props={"description": "Raw orders ingested from the upstream order system."},
            source_id=source_id,
            ontology_version=_ONTOLOGY,
        ),
        Entity(
            type="Table",
            name="stg_orders",
            external_id="table:stg_orders",
            props={"description": "Cleaned orders, derived from source_orders."},
            source_id=source_id,
            ontology_version=_ONTOLOGY,
        ),
        Entity(
            type="Dashboard",
            name="mart_orders",
            external_id="dashboard:mart_orders",
            props={"description": "Orders dashboard aggregate, derived from stg_orders."},
            source_id=source_id,
            ontology_version=_ONTOLOGY,
        ),
        Entity(
            type="Job",
            name="refresh_stg_orders",
            external_id="job:refresh_stg_orders",
            props={
                "description": "Refresh job that loads source_orders into stg_orders.",
                "is_stale": True,
                "last_success_at": "2025-01-01T00:00:00Z",
            },
            source_id=source_id,
            ontology_version=_ONTOLOGY,
        ),
    ]


def _lineage_edges(source_id: str) -> list[Edge]:
    """Return DERIVED_FROM / WRITES_TO / READS_FROM edges for the lineage chain."""
    return [
        Edge(
            src_external_id="table:stg_orders",
            dst_external_id="table:source_orders",
            relation="DERIVED_FROM",
            confidence=1.0,
            source_id=source_id,
            ontology_version=_ONTOLOGY,
        ),
        Edge(
            src_external_id="dashboard:mart_orders",
            dst_external_id="table:stg_orders",
            relation="DERIVED_FROM",
            confidence=1.0,
            source_id=source_id,
            ontology_version=_ONTOLOGY,
        ),
        Edge(
            src_external_id="job:refresh_stg_orders",
            dst_external_id="table:source_orders",
            relation="READS_FROM",
            confidence=1.0,
            source_id=source_id,
            ontology_version=_ONTOLOGY,
        ),
        Edge(
            src_external_id="job:refresh_stg_orders",
            dst_external_id="table:stg_orders",
            relation="WRITES_TO",
            confidence=1.0,
            source_id=source_id,
            ontology_version=_ONTOLOGY,
        ),
    ]


# ---------------------------------------------------------------------------
# Main seed
# ---------------------------------------------------------------------------

def seed(fixtures_dir: Path, database_url: str) -> None:
    # 1. Generate (or refresh) fixture files.
    print(f"Generating fixtures in {fixtures_dir} ...")
    _generate_fixtures(fixtures_dir)
    print("  done.")

    docs_dir = fixtures_dir / "docs"

    with psycopg.connect(database_url) as conn:
        with conn.transaction():
            # 2. Register demo sources.
            print("Registering demo sources ...")
            lineage_source_id = _upsert_source(
                conn,
                type_="git",
                uri=str(fixtures_dir / "repos" / "sql-dbt-sample"),
                owner="demo",
                sensitivity="internal",
            )
            docs_source_id = _upsert_source(
                conn,
                type_="document",
                uri=str(docs_dir),
                owner="demo",
                sensitivity="internal",
            )
            print(f"  lineage source: {lineage_source_id}")
            print(f"  docs source:    {docs_source_id}")

            # 3. Seed lineage chain entities and edges.
            print("Upserting lineage chain entities ...")
            entity_id_map: dict[str, str] = {}
            for entity in _lineage_entities(lineage_source_id):
                db_id = _upsert_entity(conn, lineage_source_id, entity)
                entity_id_map[entity.external_id] = db_id
                print(f"  {entity.type} {entity.name!r} -> {db_id}")

            print("Upserting lineage chain edges ...")
            for edge in _lineage_edges(lineage_source_id):
                _upsert_edge(conn, lineage_source_id, edge, entity_id_map)
                print(f"  {edge.relation}: {edge.src_external_id} -> {edge.dst_external_id}")

            # 4. Run DocumentHarvester for policy/FAQ docs.
            print("Running DocumentHarvester for fixture docs ...")
            harvester = DocumentHarvester()
            source_dict = {"uri": str(docs_dir)}
            conn_result = harvester.connect(source_dict)
            if not conn_result.ok:
                raise RuntimeError(f"DocumentHarvester connect failed: {conn_result.error}")

            scope = harvester.discover(source_dict)
            profile = harvester.profile(source_dict, scope)
            plan = harvester.plan(profile)

            doc_entity_id_map: dict[str, str] = {}
            for raw in harvester.harvest(source_dict, plan, cursor=None):
                normalized = harvester.normalize(raw)
                for item in normalized:
                    if isinstance(item, Entity):
                        item_with_source = Entity(
                            type=item.type,
                            name=item.name,
                            external_id=item.external_id,
                            props=item.props,
                            source_id=docs_source_id,
                            ontology_version=_ONTOLOGY,
                        )
                        db_id = _upsert_entity(conn, docs_source_id, item_with_source)
                        doc_entity_id_map[item.external_id] = db_id
                        print(f"  Document {item.name!r} (sensitivity={item.props.get('sensitivity')}) -> {db_id}")

            for raw in harvester.harvest(source_dict, plan, cursor=None):
                normalized = harvester.normalize(raw)
                for item in normalized:
                    if isinstance(item, Chunk):
                        _insert_chunk(conn, docs_source_id, item, doc_entity_id_map)
                        print(f"  Chunk for {item.entity_external_id!r}: {item.text[:60]!r}...")

        print("\nSeed complete.")
        print(f"  Lineage entities: {len(entity_id_map)}")
        print(f"  Document entities: {len(doc_entity_id_map)}")


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--fixtures-dir",
        type=Path,
        default=ROOT / "fixtures",
        help="Output directory for generated fixtures (default: <repo-root>/fixtures)",
    )
    parser.add_argument(
        "--database-url",
        default=os.environ.get(
            "DATABASE_URL", "postgresql://postgres:postgres@localhost:5432/postgres"
        ),
        help="Postgres connection string (default: $DATABASE_URL or localhost:5432/postgres)",
    )
    args = parser.parse_args()
    seed(args.fixtures_dir, args.database_url)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
